#include <vector>
#include <unordered_map>

class Solution {
public:
    int sumOfGoodSubsequences(std::vector<int>& nums) {
        const int MOD = 1000000007;
        std::unordered_map<int, long long> count;
        std::unordered_map<int, long long> total_sum;

        for (int x : nums) {
            long long c = (1 + count[x - 1] + count[x + 1]) % MOD;
            long long s = ((long long)x * c + total_sum[x - 1] + total_sum[x + 1]) % MOD;
            count[x] = (count[x] + c) % MOD;
            total_sum[x] = (total_sum[x] + s) % MOD;
        }

        long long ans = 0;
        for (auto& pair : total_sum) {
            ans = (ans + pair.second) % MOD;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int sumOfGoodSubsequences(int[] nums) {
        long MOD = 1_000_000_007;
        Map<Integer, Long> count = new HashMap<>();
        Map<Integer, Long> totalSum = new HashMap<>();

        for (int x : nums) {
            long c = (1 + count.getOrDefault(x - 1, 0L) + count.getOrDefault(x + 1, 0L)) % MOD;
            long s = ((long) x * c + totalSum.getOrDefault(x - 1, 0L) + totalSum.getOrDefault(x + 1, 0L)) % MOD;
            count.put(x, (count.getOrDefault(x, 0L) + c) % MOD);
            totalSum.put(x, (totalSum.getOrDefault(x, 0L) + s) % MOD);
        }

        long ans = 0;
        for (long val : totalSum.values()) {
            ans = (ans + val) % MOD;
        }
        return (int) ans;
    }
}

